mapper.select:
select r.id, r.refund_no, r.order_id, r.order_code, r.user_id, r.business_org_id
     , r.refund_amount, r.reason_type, r.reason, r.refund_status
     , r.audit_user_id, r.audit_time, r.audit_remark, r.create_time
from oms_order_refund r
where r.invalid = 0
and r.id = #{filter.id}
and r.refund_no = #{filter.refundNo}
and r.order_code = #{filter.orderCode}
and r.order_id = #{filter.orderId}
and r.user_id = #{filter.userId}
and r.refund_status = #{filter.refundStatus}
order by r.id desc
